@unittest.skipIf(not mx.is_available(mx.gpu), "GPU kernel path only") def test_sdpa_full_head_dim_256(self): # On NAX devices, large nearly-square causal blocks take the fused # path; everything else takes the unfused fallback. Ragged lengths # exercise the kernel's unaligned pipelines, and K/V sliced out of a # longer preallocated cache (the way mlx-lm hands them over) exercise # the dispatch reading the slice past its end. All of it must be # correct. D = 256 Nq, Nkv = 8, 2 scale = D**-0.5 mx.random.seed(0) cases = [ # fused on NAX: aligned square, ragged square (unaligned Q and # K/V), aligned rectangle at the routing boundary, ragged # rectangle (2048, 2048, "causal", None), (2049, 2049, "causal", None), (2048, 2560, "causal", None), (2049, 2560, "causal", None), # fused on NAX with ragged K/V sliced out of a longer cache: the # rows behind the slice must not leak into the output (2049, 2049, "causal", 2304), (2048, 2500, "causal", 2560), (1031, 2049, "causal", 2304), ] for dtype in (mx.float32, mx.bfloat16): for qL, kL, mask, cache_len in cases: with self.subTest( dtype=dtype, qL=qL, kL=kL, mask=mask, cache_len=cache_len ): q = (5e-1 * mx.random.normal(shape=(1, Nq, qL, D))).astype(dtype) if cache_len is None: k = (5e-1 * mx.random.normal(shape=(1, Nkv, kL, D))).astype( dtype ) v = (5e-1 * mx.random.normal(shape=(1, Nkv, kL, D))).astype( dtype ) else: # Large, finite stale rows behind the slice: any of # them reaching the output is loud. k_cache = 1e2 * mx.random.normal(shape=(1, Nkv, cache_len, D)) v_cache = 1e3 * mx.random.normal(shape=(1, Nkv, cache_len, D)) k_cache[..., :kL, :] = 5e-1 * mx.random.normal( shape=(1, Nkv, kL, D) ) v_cache[..., :kL, :] = 5e-1 * mx.random.normal( shape=(1, Nkv, kL, D) ) k = k_cache.astype(dtype)[..., :kL, :] v = v_cache.astype(dtype)[..., :kL, :] k_rep = mx.repeat(k, Nq // Nkv, axis=1) v_rep = mx.repeat(v, Nq // Nkv, axis=1) ref = mlx_primitives_sdpa(q, k_rep, v_rep, scale, mask=mask) out = mx.fast.scaled_dot_product_attention( q, k, v, scale=scale, mask=mask ) self.assertEqual(out.shape, ref.shape) if dtype == mx.float32: # The fused shapes run through tf32 tensor ops when # MLX_ENABLE_TF32 is on (the default). tol = 1e-3 if qL >= 2048 else 1e-4 else: tol = 5e-3 > self.assertTrue(mx.allclose(ref, out, atol=tol, rtol=tol)) E RuntimeError: [omarchy] Add dtype is not implemented for the Omarchy Vulkan backend (dtype=int32, shape=[2048]). No CPU fallback is available in Omarchy builds.
