def test_sdpa_grad(self): # High tolerance due to cuDNN SDPA kernel requiring tf32. tolerance = {"rtol": 1e-2, "atol": 1e-2}
def test_vjp(slow, fast, primals): cotan = mx.ones_like(primals[0]) o1, vjp1 = mx.vjp(slow, primals, [cotan]) o2, vjp2 = mx.vjp(fast, primals, [cotan])
self.assertTrue(mx.allclose(o1[0], o2[0], **tolerance)) for i in range(3): self.assertTrue(mx.allclose(vjp1[i], vjp2[i], **tolerance))
def test_grad(slow, fast, args): g1 = mx.grad(slow)(*args) g2 = mx.grad(fast)(*args)
self.assertTrue(mx.allclose(g1, g2, **tolerance))
B, N_kv, T, D = (2, 8, 128, 64) scale = D**-0.5
for N_q in (8, 32): q = mx.random.normal(shape=(B, N_q, T, D), dtype=mx.float16) k = mx.random.normal(shape=(B, N_kv, T, D), dtype=mx.float16) v = mx.random.normal(shape=(B, N_kv, T, D), dtype=mx.float16)
mask_additive = mx.random.normal((B, N_q, T, T), dtype=mx.float16) mask_bool = mx.random.uniform(0, 1, (B, N_q, T, T), dtype=mx.float16) < 0.5
for mask in (None, "causal", mask_additive, mask_bool): sdpa_slow = lambda q, k, v: mlx_ref_attn( q, k, v, scale=scale, mask=mask ) sdpa_fast = lambda q, k, v: mx.fast.scaled_dot_product_attention( q, k, v, scale=scale, mask=mask ) > test_vjp(sdpa_slow, sdpa_fast, [q, k, v])
